SELECT v.idVenta as id, u.nombre AS cliente, COALESCE(STRING_AGG(p.nombre || ' x' || dv.cantidad::text, ', ' ORDER BY p.nombre), anterior.nombre) AS servicio, TO_CHAR((v.fecha AT TIME ZONE current_setting('TimeZone') AT TIME ZONE 'America/Mexico_City'), 'YYYY-MM-DD') AS fecha_iso, TO_CHAR((v.fecha AT TIME ZONE current_setting('TimeZone') AT TIME ZONE 'America/Mexico_City'), 'FMDD/FMMM/YYYY') AS fecha, v.total, v.metodo_pago FROM Venta v LEFT JOIN Usuarios u ON u.idUsuarios = v.idUsuarios LEFT JOIN DetalleVenta dv ON dv.idVenta = v.idVenta LEFT JOIN Productos p ON p.idProductos = dv.idProductos LEFT JOIN Productos anterior ON anterior.idProductos = v.idProductos WHERE $1::date IS NULL OR ( v.fecha >= ($1::date::timestamp AT TIME ZONE 'America/Mexico_City' AT TIME ZONE current_setting('TimeZone')) AND v.fecha < (($1::date + 1)::timestamp AT TIME ZONE 'America/Mexico_City' AT TIME ZONE current_setting('TimeZone')) ) GROUP BY v.idVenta, u.nombre, v.fecha, v.total, v.metodo_pago, anterior.nombre ORDER BY v.fecha DESC, v.idVenta DESC